from __future__ import annotations

def calc(expr: str) -> int | str:
    ERROR = "error"
    vals = []
    ops = []
    n = len(expr)
    i = 0
    last = None

    prec = {'^': 3, 'u': 2, '*': 1, '/': 1, '%': 1, '+': 0, '-': 0}
    left = {'*': True, '/': True, '%': True, '+': True, '-': True, '^': False, 'u': False}

    def apply(op):
        if op == 'u':
            a = vals.pop()
            vals.append(ERROR if a == ERROR else -a)
            return

        b = vals.pop()
        a = vals.pop()
        if a == ERROR or b == ERROR:
            vals.append(ERROR)
            return

        if op == '+':
            vals.append(a + b)
        elif op == '-':
            vals.append(a - b)
        elif op == '*':
            vals.append(a * b)
        elif op == '/':
            if b == 0:
                vals.append(ERROR)
            else:
                q = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    q = -q
                vals.append(q)
        elif op == '%':
            if b == 0:
                vals.append(ERROR)
            else:
                q = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    q = -q
                vals.append(a - b * q)
        elif op == '^':
            if b < 0:
                vals.append(ERROR)
            elif a == 0:
                vals.append(1 if b == 0 else 0)
            elif a == 1:
                vals.append(1)
            elif a == -1:
                vals.append(1 if b % 2 == 0 else -1)
            else:
                vals.append(pow(a, b))

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue

        if '0' <= c <= '9':
            v = 0
            while i < n and '0' <= expr[i] <= '9':
                v = v * 10 + (ord(expr[i]) - 48)
                i += 1
            vals.append(v)
            last = 'num'
            continue

        if c == '(':
            ops.append(c)
            last = 'lparen'
            i += 1
            continue

        if c == ')':
            while ops and ops[-1] != '(':
                apply(ops.pop())
            ops.pop()
            last = 'rparen'
            i += 1
            continue

        if c == '-':
            if last is None or last == 'lparen' or last == 'op':
                op = 'u'
            else:
                op = '-'
        else:
            op = c

        if op == 'u':
            ops.append(op)
        else:
            while ops and ops[-1] != '(':
                top = ops[-1]
                if prec[top] > prec[op] or (prec[top] == prec[op] and left[op]):
                    apply(ops.pop())
                else:
                    break
            ops.append(op)

        last = 'op'
        i += 1

    while ops:
        apply(ops.pop())

    return vals[0] if vals else ERROR
